const sample = {
  "demo": true,
  "url": "https://example.com/place/lumen",
  "html": "<title>Lumen Freight</title><p>+1 555 555 0190</p>",
  "company": "Lumen Freight",
  "phone": "+15555550190"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const html = String(item.html || '');
const wanted = ['company', 'phone', 'title'];
const record = { url: item.url || '', fetchedAt: item.fetchedAt || new Date().toISOString() };
for (const field of wanted) {
  if (item[field]) record[field] = item[field];
}
if (!record.email) {
  const found = html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  if (found) record.email = found[0].toLowerCase();
}
if (!record.phone) {
  const found = html.match(/\+?[0-9][0-9()\-\s]{8,}/);
  if (found) record.phone = found[0].trim();
}
if (!record.title) {
  const found = html.match(/<title>([^<]+)<\/title>/i);
  if (found) record.title = found[1].trim();
}
const missing = wanted.filter((field) => !record[field]);
const route = missing.length === 0 ? 'complete' : missing.length < wanted.length ? 'partial' : 'empty';
return {
  summary: (record.title || record.url || 'Page') + ' extracted with route ' + route + '.',
  route,
  record: { ...record, missing: missing.join(',') },
  slackText: route.toUpperCase() + ' scrape ' + (record.url || ''),
  actions: [{ app: 'Google Sheets', operation: 'append', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'maps-style-lead-list',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
